mapper.sql:
FROM platform_account a JOIN platform p ON p.id=a.platform_id JOIN creator c ON c.id=a.creator_id WHERE 1=1
 AND (
a.creator_id=#{creatorId}
 OR 
EXISTS(SELECT 1 FROM project_member pm JOIN project pr ON pr.id=pm.project_id WHERE pm.creator_id=a.creator_id AND pr.owner_id=#{productionOwnerId})
)
 AND (a.name LIKE CONCAT('%',#{q},'%') OR c.name LIKE CONCAT('%',#{q},'%')) AND a.status=#{status}

sql.if:
 AND (
p.owner_id=#{productionOwnerId}
 OR 
EXISTS(SELECT 1 FROM project_member pm WHERE pm.project_id=p.id AND pm.creator_id=#{creatorId})
)

mapper.sql:
FROM asset a JOIN creator c ON c.id=a.creator_id WHERE 1=1
 AND (
a.creator_id=#{creatorId} OR 
EXISTS(SELECT 1 FROM project_asset pa JOIN project ap ON ap.id=pa.project_id WHERE pa.asset_id=a.id AND (
ap.owner_id=#{productionOwnerId}
 OR 
EXISTS(SELECT 1 FROM project_member pm WHERE pm.project_id=ap.id AND pm.creator_id=#{creatorId})
))
)
 AND a.id=#{assetId} AND (a.name LIKE CONCAT('%',#{q},'%') OR a.description LIKE CONCAT('%',#{q},'%')) AND a.status=#{status}
